def _active_set(Q, q, C, d, eq, x0, max_iter):
    n = int(q.shape[0])
    m = int(d.shape[0])
    x = np.array(x0, dtype=float)
    keep = set(i for i in range(n) if x[i] > 0.0)
    tight = set(k for k in range(m) if eq[k])
    for k in range(m):
        if not eq[k] and float(C[k] @ x) >= float(d[k]) - 0.0:
            tight.add(k)
    for i in range(n):
        if i not in keep:
            x[i] = 0.0
    dtol = 1e-11
    for _ in range(max_iter):
        free = sorted(keep)
        ts = sorted(tight)
        xstar, lam = equality_qp(Q, q, C, d, free, ts)
        p = xstar - x
        pn = float(np.abs(p).max()) if n else 0.0
        ptol = 1e-12 * max(1.0, float(np.abs(xstar).max()) if n else 1.0)
        if pn <= ptol:
            x = xstar
            g = Q @ xstar + q
            nu = g + (C.T @ lam if m else 0.0)
            worst = None
            for i in range(n):
                if i in keep:
                    continue
                if nu[i] < -dtol and (worst is None or nu[i] < worst[0]):
                    worst = (nu[i], "b", i)
            for k in ts:
                if eq[k]:
                    continue
                if lam[k] < -dtol and (worst is None or lam[k] < worst[0]):
                    worst = (lam[k], "c", k)
            if worst is None:
                return x, lam, keep, tight, True
            if worst[1] == "b":
                keep.add(worst[2])
            else:
                tight.discard(worst[2])
            continue
        alpha = 1.0
        block = None
        for i in free:
            if p[i] < 0.0:
                a = -x[i] / p[i]
                if a < alpha:
                    alpha = a
                    block = ("b", i)
        if m:
            Cx = C @ x
            Cp = C @ p
            for k in range(m):
                if eq[k] or k in tight:
                    continue
                if Cp[k] > 0.0:
                    a = (float(d[k]) - float(Cx[k])) / float(Cp[k])
                    if a < alpha:
                        alpha = a
                        block = ("c", k)
        if alpha < 0.0:
            alpha = 0.0
        if alpha >= 1.0:
            x = xstar.copy()
        else:
            x = x + alpha * p
        for i in range(n):
            if i not in keep:
                x[i] = 0.0
        if block is not None:
            if block[0] == "b":
                keep.discard(block[1])
                x[block[1]] = 0.0
            else:
                tight.add(block[1])
        x = np.maximum(x, 0.0)
    free = sorted(keep)
    ts = sorted(tight)
    xstar, lam = equality_qp(Q, q, C, d, free, ts)
    return xstar, lam, keep, tight, False
